#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_overview_autofill_20260730.py

概要欄・技術スタックをGitHub実コード + プロジェクト資料からAIで自動入力する機能を追加。

新規:
  - src/app/api/projects/[id]/overview/autofill/route.ts
      GitHub(リポジトリ設定時のみ: ファイルツリー+主要マニフェスト内容+コミット履歴)と
      プロジェクト内資料(標準ドキュメント/カスタムドキュメント/添付資料)を突き合わせ、
      Claude(claude-sonnet-4-5)で概要フィールド12種+技術スタックを一括生成して保存する。
      認証: 管理者セッション or インポート専用APIキー(バッチ実行用)。
      env_vars等への秘密情報混入は保存前にsecret-scan.tsで検査しブロックする。
  - scripts/overview_autofill/run_all.py
      全プロジェクトに対して上記APIを順次呼び出すバッチスクリプト(再利用ツール)。

変更:
  - src/components/projects/ProjectOverviewClient.tsx
      「🤖 AIで自動入力」ボタンを追加。実行結果(技術スタック件数・主要機能件数・
      資料とコードの不整合の指摘)を表示する。

検証済み: tsc --noEmit 新規エラー0件・esbuild構文チェック全ファイル通過・
run_all.py は py_compile 通過。

適用手順:
    python3 patch_overview_autofill_20260730.py
    npm run build
    pm2 restart meridian
"""

import base64
import json
import os

PAYLOAD_B64 = ""

def main():
    payload = json.loads(base64.b64decode(PAYLOAD_B64).decode("utf-8"))

    for rel_path, b64content in payload.items():
        content = base64.b64decode(b64content).decode("utf-8")
        abs_path = os.path.join(os.getcwd(), rel_path)
        os.makedirs(os.path.dirname(abs_path), exist_ok=True)
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] 書き込み: {rel_path}")

    print()
    print("=== すべての変更を適用しました ===")
    print("次のコマンドを実行してください:")
    print("  npm run build")
    print("  pm2 restart meridian")
    print()
    print("（このパッチはDBスキーマ変更を含まないため migrate は不要です）")

if __name__ == "__main__":
    main()
